<?php
/**
 * Ministrant Manager - atomic hardening for legacy Witosa maintenance/admin files.
 *
 * Run from /home/<user>/, next to public_html/:
 *   php apply_legacy_security_hardening.php
 *
 * Security goals:
 * - disable web-accessible one-off maintenance/reset/upload scripts,
 * - harden public/settings.php with CSRF and a non-predictable factory-reset password,
 * - fail closed on an unknown production baseline,
 * - backup and rollback atomically on any write/verification failure.
 */
declare(strict_types=1);

$publicRoot = __DIR__ . '/public_html';
if (!is_dir($publicRoot)) {
    fwrite(STDERR, "ERROR: expected public_html/ next to this script.\n");
    exit(1);
}

$plan = json_decode('{"upd.php":{"baseline":"da6930bdc95f7dae76008e6cb36452ce38441186d598e7b1ef7e1826479382a5","patched":"52eaa94241f945b8ad3914b45e18dd9549895c4072838fbf3b29f10622c77739","content":"PD9waHAKaHR0cF9yZXNwb25zZV9jb2RlKDQwMyk7CmhlYWRlcignQ29udGVudC1UeXBlOiB0ZXh0L3BsYWluOyBjaGFyc2V0PXV0Zi04Jyk7CmhlYWRlcignQ2FjaGUtQ29udHJvbDogbm8tc3RvcmUnKTsKZWNobyAiV2Vib3d5IHVwZGF0ZXIgamVzdCB3ecWCxIVjem9ueSBwcm9kdWtjeWpuaWUuIFXFvHlqIHdlcnNqb25vd2FuZWogcGFjemtpIHdkcm/FvGVuaW93ZWouXG4iOwpleGl0Owo="},"reset.php":{"baseline":"89ea9d58ada5ad36847d4acbf1fe907d8ffc70caa8fc28db252b66caba9ae9db","patched":"d3d0f85875c7e68299de536f0f1f193d2b09aaad65838e12a3fedec55cfb7c0c","content":""},"receiver.php":{"baseline":"23faa6cc85b650804d0fc01242f64be9ad71364bd1dc97424c3b401f1f5548b9","patched":"6fa6152fe68934b7075cc288be5395bd11f3f408e8a33fe81371aad97d1ff0c1","content":""},"fix.php":{"baseline":"62973c609a3304770916b6630a993ed8d96c15d58dae5c001b1723bc20907aec","patched":"c811ebbd400a75ccf5ab3714dcda833fe94dd488945f6cc6e62ee8dd17db2d79","content":"PD9waHAKaHR0cF9yZXNwb25zZV9jb2RlKDQwMyk7CmhlYWRlcignQ29udGVudC1UeXBlOiB0ZXh0L3BsYWluOyBjaGFyc2V0PXV0Zi04Jyk7CmhlYWRlcignQ2FjaGUtQ29udHJvbDogbm8tc3RvcmUnKTsKZWNobyAiSmVkbm9yYXpvd3kgc2tyeXB0IG5hcHJhd2N6eSBqZXN0IHd5xYLEhWN6b255IHByb2R1a2N5am5pZS5cbiI7CmV4aXQ7Cg=="},"public/settings.php":{"baseline":"4e48804785b9fec10c2cd290dffedbad48f15f501b91e1a9dcdcd65f56b86504","patched":"546864b96b682943f4937a494e4c75029f40964f4df675d350b4ac36286467bc","content":""}}', true, 512, JSON_THROW_ON_ERROR);

function mm_fail(string $message): never {
    fwrite(STDERR, "ERROR: $message\n");
    exit(1);
}

function mm_atomic_write(string $path, string $content): void {
    $dir = dirname($path);
    if (!is_dir($dir)) {
        throw new RuntimeException("Missing directory: $dir");
    }
    $mode = file_exists($path) ? (fileperms($path) & 0777) : 0644;
    $tmp = tempnam($dir, '.mm-hardening-');
    if ($tmp === false) {
        throw new RuntimeException("Could not create temp file for $path");
    }
    try {
        if (file_put_contents($tmp, $content, LOCK_EX) === false) {
            throw new RuntimeException("Could not write temp file for $path");
        }
        @chmod($tmp, $mode);
        if (!rename($tmp, $path)) {
            throw new RuntimeException("Could not atomically replace $path");
        }
    } finally {
        if (is_file($tmp)) @unlink($tmp);
    }
}

// Preflight every file before touching any of them.
$states = [];
foreach ($plan as $relative => $entry) {
    $path = $publicRoot . '/' . $relative;
    if (!is_file($path)) {
        $states[$relative] = 'skipped_missing';
        continue;
    }
    $current = hash_file('sha256', $path);
    if ($current === $entry['patched']) {
        $states[$relative] = 'patched';
        continue;
    }
    if ($current !== $entry['baseline']) {
        $states[$relative] = 'skipped_modified';
        continue;
    }
    $states[$relative] = 'baseline';
}

$needsWork = array_filter($states, static fn(string $state): bool => $state === 'baseline');
$missing = array_keys(array_filter($states, static fn(string $state): bool => $state === 'skipped_missing'));
if ($missing) {
    echo "WARN: optional legacy files missing; skipped: " . implode(', ', $missing) . "\n";
}
if (!$needsWork) {
    echo "LEGACY SECURITY HARDENING: nothing to change\n";
    exit(0);
}

$backupDir = __DIR__ . '/backup_legacy_security_' . date('Ymd_His');
if (!mkdir($backupDir, 0700, true) && !is_dir($backupDir)) {
    mm_fail("Could not create backup directory: $backupDir");
}

$changed = [];
try {
    foreach ($states as $relative => $state) {
        if ($state !== 'baseline') continue;
        $source = $publicRoot . '/' . $relative;
        $backup = $backupDir . '/' . $relative;
        $backupParent = dirname($backup);
        if (!is_dir($backupParent) && !mkdir($backupParent, 0700, true) && !is_dir($backupParent)) {
            throw new RuntimeException("Could not create backup directory: $backupParent");
        }
        if (!copy($source, $backup)) {
            throw new RuntimeException("Could not back up $relative");
        }
        if (hash_file('sha256', $backup) !== $plan[$relative]['baseline']) {
            throw new RuntimeException("Backup verification failed for $relative");
        }
    }

    foreach ($states as $relative => $state) {
        if ($state !== 'baseline') continue;
        $content = base64_decode($plan[$relative]['content'], true);
        if ($content === false) {
            throw new RuntimeException("Invalid embedded payload for $relative");
        }
        $target = $publicRoot . '/' . $relative;
        mm_atomic_write($target, $content);
        $changed[] = $relative;
        $actual = hash_file('sha256', $target);
        if ($actual !== $plan[$relative]['patched']) {
            throw new RuntimeException("Post-write SHA-256 mismatch for $relative: $actual");
        }
    }

    echo "LEGACY SECURITY HARDENING OK\n";
    echo "Backup: $backupDir\n";
    foreach ($changed as $relative) echo "  hardened: $relative\n";
    exit(0);
} catch (Throwable $e) {
    fwrite(STDERR, "Hardening failed: " . $e->getMessage() . "\nRolling back...\n");
    foreach (array_reverse($changed) as $relative) {
        $backup = $backupDir . '/' . $relative;
        $target = $publicRoot . '/' . $relative;
        if (is_file($backup)) {
            @copy($backup, $target);
        }
    }
    fwrite(STDERR, "Rollback finished. Backup kept at: $backupDir\n");
    exit(1);
}